function o(t){if(!t)return"-";const e=new Date(t);if(isNaN(e.getTime()))return"-";const r=n=>String(n).padStart(2,"0");return`${e.getFullYear()}-${r(e.getMonth()+1)}-${r(e.getDate())} ${r(e.getHours())}:${r(e.getMinutes())}:${r(e.getSeconds())}`}function a(t){if(!t)return"-";const e=new Date(t).getTime();if(isNaN(e))return"-";const r=Math.floor((Date.now()-e)/1e3);if(r<60)return"刚刚";const n=Math.floor(r/60);if(n<60)return`${n}分钟前`;const u=Math.floor(n/60);if(u<24)return`${u}小时前`;const i=Math.floor(u/24);return i<30?`${i}天前`:o(t).slice(0,10)}function s(t){return t==="left_glove"||t==="left_dexterous_hand"?"left":t==="right_glove"||t==="right_dexterous_hand"?"right":t.endsWith("_left")?"left":t.endsWith("_right")?"right":null}function f(t){return t==="left_glove"||t==="right_glove"||t==="left_dexterous_hand"||t==="right_dexterous_hand"||t.endsWith("_left")||t.endsWith("_right")}function l(t,e){return t==="glove"?e==="left"?"左手手套":"右手手套":t==="dexterous_hand"?e==="left"?"左手灵巧手":e==="right"?"右手灵巧手":"灵巧手":t==="gripper"?"夹爪(Pika)":t||"-"}function g(t){let e=0;return t.map(r=>e+=r)}function h(t,e){const r=t.match(/^(\D*)(\d+)$/),n=e.match(/^(\D*)(\d+)$/);if(r&&n&&r[1]===n[1])return parseInt(r[2],10)-parseInt(n[2],10);const u=parseInt(t,10),i=parseInt(e,10);return!isNaN(u)&&!isNaN(i)?u-i:t.localeCompare(e,"zh-CN",{numeric:!0})}export{g as c,l as e,o as f,s as g,f as i,h as n,a as r};
